import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def x_k(k, n):
    if n == 0:
        return 1
    numbers = list(range(k, k + n))
    return list_lcm(numbers)

# Test n=4
n = 4
print(f"Testing n={n}")
for k in range(1, 30):
    x_k_val = x_k(k, n)
    x_k_plus_1_val = x_k(k+1, n)

    # Check for x_{k+1} <= x_k
    if x_k_plus_1_val <= x_k_val:
        print(f"Counterexample found at k={k}: x_{k+1} ({x_k_plus_1_val}) <= x_k ({x_k_val})")
        exit()

    if k % 5 == 0:
        print(f"k={k}: x_k = {x_k_val}")

print("No counterexample found for k up to 29.")

import math

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_of_sequence(start, length):
    if length == 0:
        return 1
    result = start
    for i in range(start + 1, start + length):
        result = lcm(result, i)
    return result

n = 5
k_values = range(1, 11)
x_values = {}
print("k | x_k")
print("-" * 15)
for k in k_values:
    x_k = lcm_of_sequence(k, n)
    x_values[k] = x_k
    print(f"{k} | {x_k}")

print("\nComparison x_{k+1} vs x_k:")
for k in range(1, 10):
    x_k = x_values[k]
    x_k_plus_1 = x_values[k+1]
    comparison = ""
    if x_k_plus_1 > x_k:
        comparison = " > "
    elif x_k_plus_1 < x_k:
        comparison = " < "
    else:
        comparison = " = "
    print(f"k={k}: x_{k+1} ({x_k_plus_1}) {comparison} x_k ({x_k})")

import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

N = 6
K_MAX = 10
results = {}

for k in range(1, K_MAX + 1):
    # x_k = lcm(k, k+1, ..., k+N-1) = lcm(k, k+1, ..., k+5)
    sequence = list(range(k, k + N))
    x_k = list_lcm(sequence)
    results[k] = x_k

print("Calculated x_k for k=1 to 10:")
for k, xk in results.items():
    print(f"k={k}: x_{k} = {xk}")

print("\nChecking x_{k+1} > x_k for k=1 to 9:")
for k in range(1, K_MAX):
    x_k = results[k]
    x_k_plus_1 = results[k+1]
    is_increasing = x_k_plus_1 > x_k
    print(f"k={k}: x_{k+1} = {x_k_plus_1}, x_k = {x_k}. Is x_{k+1} > x_k? {is_increasing}")

import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Test n=6
n = 6
x_values = {}

# Calculate x_k for k=1 to 6
for k in range(1, 7):
    numbers = list(range(k, k + n))
    x_k = list_lcm(numbers)
    x_values[k] = x_k
    print(f"x_{k} (n={n}) = {x_k}")

# Check the condition for weakly increasing: exists N such that x_{k+1} > x_k for k > N
# We observe the sequence: 60, 420, 840, 2520, 2520, 27720
print("\nChecking transitions:")
for k in range(1, 6):
    if x_values[k+1] > x_values[k]:
        print(f"k={k}: x_{k+1} > x_k (Increase)")
    elif x_values[k+1] < x_values[k]:
        print(f"k={k}: x_{k+1} < x_k (Decrease - Failure)")
    else:
        print(f"k={k}: x_{k+1} = x_k (Plateau)")

